import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"How we protect your data","description":"","frontmatter":{},"headers":[],"relativePath":"en/privacidad/index.md","filePath":"en/privacidad/index.md","lastUpdated":null}'),n={name:"en/privacidad/index.md"};function i(s,e,u,h,l,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-we-protect-your-data" tabindex="-1">How we protect your data <a class="header-anchor" href="#how-we-protect-your-data" aria-label="Permalink to &quot;How we protect your data&quot;">​</a></h1><p>This page explains what we do with data, without fine print. If anything here does not match the code (which is public), the code wins, and we want to know.</p><h2 id="what-we-promise" tabindex="-1">What we promise <a class="header-anchor" href="#what-we-promise" aria-label="Permalink to &quot;What we promise&quot;">​</a></h2><ol><li><strong>We never store phone numbers.</strong> We store a code computed from the number with a secret key (HMAC-SHA256). Someone who stole the database would not get any numbers.</li><li><strong>Your address book is not stored as an address book.</strong> Nobody can see &quot;the contacts of a person&quot;.</li><li><strong>A name is only shown if at least 3 different people saved it the same way.</strong></li><li><strong>Nobody can search for a person by name.</strong> You only see a name if you already have the number, because they called you.</li><li><strong>Names are stored encrypted</strong> with a key that depends on each number.</li><li><strong>We do not store who looked up which number.</strong> Call history lives only on your phone.</li><li><strong>You can withdraw your contribution and delete your account at any time.</strong> Anyone can ask us to hide the names linked to their number.</li></ol><h2 id="what-we-do-not-promise-and-why" tabindex="-1">What we do not promise (and why) <a class="header-anchor" href="#what-we-do-not-promise-and-why" aria-label="Permalink to &quot;What we do not promise (and why)&quot;">​</a></h2><p>We do not say it is &quot;impossible&quot; to recover a number from its code. There are few possible phone numbers, so whoever holds the <strong>secret key</strong> could compute the codes of all of them and compare. That is why the key lives outside the database and is protected as the most important part of the system.</p><h2 id="your-account" tabindex="-1">Your account <a class="header-anchor" href="#your-account" aria-label="Permalink to &quot;Your account&quot;">​</a></h2><ul><li>You sign up with email and password (and soon with Google) through Firebase Authentication.</li><li><strong>Your phone number is not linked to your account.</strong></li><li>We store when you accepted the terms and which version, as the law requires.</li></ul><h2 id="contributing-your-address-book" tabindex="-1">Contributing your address book <a class="header-anchor" href="#contributing-your-address-book" aria-label="Permalink to &quot;Contributing your address book&quot;">​</a></h2><p>It is <strong>optional</strong>; the app works the same without contributing.</p><p>If you decide to contribute:</p><ul><li>The app sends numbers and names over an encrypted connection.</li><li>The server turns each number into its code and encrypts each name. It never stores the number.</li><li>Names that describe a relationship (&quot;Mom&quot;, &quot;My love&quot;, &quot;Boss&quot;) <strong>are not used</strong>; only the fact that someone saved that number counts.</li><li>Each contribution is recorded with an identifier that is not directly tied to your account.</li><li>You can <strong>stop contributing</strong> in Settings: everything you contributed is deleted.</li></ul><h2 id="what-stays-on-your-phone" tabindex="-1">What stays on your phone <a class="header-anchor" href="#what-stays-on-your-phone" aria-label="Permalink to &quot;What stays on your phone&quot;">​</a></h2><ul><li>Your list of blocked numbers.</li><li>Your blocking settings.</li><li>Call history (30 days, up to 200 calls).</li><li>A cache of recent lookups (24 hours), to identify repeat callers faster.</li></ul><h2 id="your-rights" tabindex="-1">Your rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your rights&quot;">​</a></h2><p>You can access, update, correct and delete your data, and revoke your authorization. From the app:</p><ul><li><strong>Account → See what data we keep.</strong></li><li><strong>Account → Delete my account</strong>: deletes your account, your reports and your contributions.</li></ul><p>If you do not have an account and your number is shown wrongly, see <a href="/Tranqui/en/guia/apelacion">Is your number shown wrongly?</a>.</p><p>Legal details are in the <a href="/Tranqui/en/legal/politica-de-tratamiento">Data processing policy</a>.</p>',19)])])}const y=o(n,[["render",i]]);export{p as __pageData,y as default};
